// Complete source bundle. Run: node restore-source.mjs
import {brotliDecompressSync} from 'node:zlib';
import {mkdirSync,writeFileSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
const files=JSON.parse(brotliDecompressSync(Buffer.from('','base64')).toString());
for(const [name,data] of Object.entries(files)){const path=resolve(name);mkdirSync(dirname(path),{recursive:true});writeFileSync(path,Buffer.from(data,'base64'));}
console.log('Restored '+Object.keys(files).length+' source files. See README.md.');
